from enum import Enum
from typing import Any, Literal
from pydantic import Field
from .base import Model


class AlertType(str, Enum):
    DATA_MODE_UNSPECIFIED = "DATA_MODE_UNSPECIFIED"
    MISSING_RECIPE = "MISSING_RECIPE"
    INVALID_INPUT = "INVALID_INPUT"
    DUPLICATE_RECIPE = "DUPLICATE_RECIPE"
    UNUSED_TRIM_POLICY = "UNUSED_TRIM_POLICY"
    MISSING_INVENTORY = "MISSING_INVENTORY"
    UNDER_PREPARATION = "UNDER_PREPARATION"
    OVER_PREPARATION = "OVER_PREPARATION"
    STOCK_SHORTAGE = "STOCK_SHORTAGE"
    MISSING_PLANNED_ORDER = "MISSING_PLANNED_ORDER"
    UNDER_ORDER = "UNDER_ORDER"
    OVER_ORDER = "OVER_ORDER"
    UNMATCHED_ORDER = "UNMATCHED_ORDER"
    HARD_CONSTRAINT_VIOLATION = "HARD_CONSTRAINT_VIOLATION"
    MISSING_CONSTRAINT_EVIDENCE = "MISSING_CONSTRAINT_EVIDENCE"
    CONSTRAINTS_NOT_CONFIGURED = "CONSTRAINTS_NOT_CONFIGURED"
    UNIT_MISMATCH = "UNIT_MISMATCH"
    DEMAND_OOD = "DEMAND_OOD"
    DEMAND_NOT_APPLICABLE = "DEMAND_NOT_APPLICABLE"
    DEMAND_EVIDENCE_UNKNOWN = "DEMAND_EVIDENCE_UNKNOWN"
    DEMAND_WARNING = "DEMAND_WARNING"
    CAPACITY_EXCEEDED = "CAPACITY_EXCEEDED"
    CAPACITY_UNSPECIFIED = "CAPACITY_UNSPECIFIED"
    INPUT_DEMAND_OUT_OF_RANGE = "INPUT_DEMAND_OUT_OF_RANGE"
    FRACTIONAL_EA_INVENTORY = "FRACTIONAL_EA_INVENTORY"
    NUMERIC_ERROR = "NUMERIC_ERROR"
    OUTPUT_PRECISION_LIMIT = "OUTPUT_PRECISION_LIMIT"
    NUTRITION_VERSION_MISMATCH = "NUTRITION_VERSION_MISMATCH"
    PROVENANCE_MISMATCH = "PROVENANCE_MISMATCH"
    OPERATION_EVIDENCE_MISSING = "OPERATION_EVIDENCE_MISSING"
    LEGACY_ROUNDING_POLICY = "LEGACY_ROUNDING_POLICY"
    COOKING_ROUNDING_EXTRA = "COOKING_ROUNDING_EXTRA"


class Trace(Model):
    trace_id: str | None = None
    step: str
    formula: str | None = None
    inputs: dict[str, Any] = Field(default_factory=dict)
    result: Any = None


class Alert(Model):
    severity: Literal["INFO", "MEDIUM", "HIGH"]
    type: AlertType
    message: str
    ingredient: str | None = None
    field: str | None = None
    evidence: dict[str, Any] = Field(default_factory=dict)
    trace_refs: list[str] = Field(default_factory=list)
